      {rewindToast && <div style={{ position:"absolute", bottom:80, left:"50%", transform:"translateX(-50%)", background:theme.greenDeep, color:"white", padding:"10px 20px", borderRadius:50, fontSize:13, fontWeight:700, zIndex:200, whiteSpace:"nowrap" }}>↩️ Rewound!</div>}
      {paywallTrigger && <Paywall trigger={paywallTrigger} onClose={() => setPaywallTrigger(null)} onSubscribe={() => { setPaywallTrigger(null); onSubscribe(); }} currentUser={currentUser} />}
      <WhoLikedYou currentUser={currentUser} isPremium={isPremium} onUpgrade={() => setPaywallTrigger("wholiked")} show={showLikers} onDismiss={() => setShowLikers(false)} onLikeBack={async (profile) => { try { await supabase.from("likes").insert({ from_user: currentUser.id, to_user: profile.id }); const [u1, u2] = [currentUser.id, profile.id].sort(); const { data: matchData } = await supabase.from("matches").upsert({ user1: u1, user2: u2 }, { onConflict: "user1,user2" }).select().maybeSingle(); setMatchPopup({ ...profile, matchId: matchData?.id }); setMatchedIds(prev => [...prev, profile.id]); if (matchData) setMatchRecords(prev => [...prev, matchData]); } catch(e) {} }} />

