        </div>
        <div style={{ marginBottom:16 }}>
          <label style={{ fontSize:12, fontWeight:600, color:theme.textMid, textTransform:"uppercase", letterSpacing:"0.05em", display:"block", marginBottom:6 }}>Bio</label>
          <textarea value={editData.bio || ""} onChange={e => setEditData(p => ({...p, bio:e.target.value.slice(0,300)}))} rows={4} style={{ width:"100%", padding:"12px 16px", borderRadius:12, border:"2px solid rgba(82,183,136,0.2)", fontFamily:"'DM Sans',sans-serif", fontSize:14, outline:"none", boxSizing:"border-box", resize:"none" }} />
          <div style={{ textAlign:"right", fontSize:11, color:(editData.bio||"").length > 270 ? theme.accent : theme.textLight }}>{300-(editData.bio||"").length} characters remaining</div>
        </div>
        {saveError && <div style={{ color:theme.accent, fontSize:12, marginBottom:10, padding:"8px 12px", background:"rgba(224,122,95,0.08)", borderRadius:8 }}>{saveError}</div>}
        <button onClick={saveProfile} style={{ ...btnPrimary, width:"100%", marginBottom:10, marginTop:10 }}>Save changes</button>
      </div>
      <BottomNav active="profile" onNav={onNav} isPremium={isPremium} unreadCount={unreadCount} />
    </PhoneShell>
  );

  return (
    <PhoneShell>
      <div style={{ padding: "16px 24px 8px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <h1 style={{ fontFamily: "Georgia,serif", fontSize: 26, fontWeight: 700, color: theme.greenDeep }}>My Profile</h1>
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={() => setShowPreview(true)} style={{ background:"none", border:"1px solid rgba(82,183,136,0.3)", borderRadius:50, padding:"6px 14px", fontSize:13, fontWeight:600, color:theme.greenMid, cursor:"pointer", fontFamily:"'DM Sans',sans-serif" }}>👁 Preview</button>
          <button onClick={onLogout} style={{ background: "none", border: "1px solid rgba(224,122,95,0.3)", borderRadius: 50, padding: "5px 12px", fontSize: 12, fontWeight: 700, color: theme.accent, cursor: "pointer", fontFamily: "inherit" }}>Sign out</button>
          <button onClick={() => setEditing(true)} style={iconBtn}>✏️</button>
        </div>
      </div>
      <div style={{ flex: 1, overflowY: "auto" }}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "18px 0 14px" }}>
          <div style={{ display:"flex", flexDirection:"column", alignItems:"center", marginBottom:10 }}>
            <div style={{ position:"relative", marginBottom:10 }}>
              <div onMouseDown={user.photo_url ? (e) => { e.preventDefault(); setDragging(true); setDragStartY(e.clientY); setDragStartOffset(photoOffsetY); } : undefined} onTouchStart={user.photo_url ? (e) => { setDragging(true); setDragStartY(e.touches[0].clientY); setDragStartOffset(photoOffsetY); } : undefined} style={{ cursor: user.photo_url ? "grab" : "default", width: 96, height: 96, borderRadius: "50%", background: "linear-gradient(135deg,#d8f3dc,#b7e4c7)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 46, border: `4px solid ${isPremium ? theme.gold : theme.greenBright}`, boxShadow: isPremium ? `0 8px 24px rgba(244,168,41,0.3)` : "0 8px 24px rgba(82,183,136,0.2)", overflow:"hidden" }}>
                {user.photo_url
                  ? <img src={user.photo_url} alt="profile" onLoad={e => setUser(u => ({ ...u, photoNaturalWidth: e.target.naturalWidth }))} style={{ width:"100%", height:"100%", objectFit:"cover", objectPosition:`${photoOffsetX}% ${photoOffsetY}%`, userSelect:"none", pointerEvents:"none" }} />
                  : <span>🌿</span>
                }
              </div>
              <div style={{ position:"absolute", bottom:0, right:0, width:30, height:30, borderRadius:"50%", background:theme.greenBright, display:"flex", alignItems:"center", justifyContent:"center", fontSize:15, boxShadow:"0 2px 8px rgba(0,0,0,0.2)", border:"2px solid white" }}>{uploading ? "⏳" : "📷"}</div>
            </div>
            {user.photo_url && !uploading && (
              <div style={{ width:"100%", padding:"4px 0 8px" }}>
                <div style={{ fontSize:11, color:theme.textLight, marginBottom:4, textAlign:"center" }}>Reposition photo</div>
                {user.photoNaturalWidth && user.photoNaturalWidth < 200 ? (
                  <div style={{ fontSize:11, color:theme.accent, textAlign:"center", padding:"4px 0" }}>⚠️ Upload a larger photo for repositioning to work</div>
                ) : (
                  <>
                    <div style={{ fontSize:10, color:theme.textLight, marginBottom:2 }}>Up / Down</div>
                    <input type="range" min="0" max="100" value={photoOffsetY} onChange={async e => { const v = Number(e.target.value); setPhotoOffsetY(v); await supabase.from("profiles").update({ photo_offset_y: v }).eq("id", currentUser.id); }} style={{ width:"100%", accentColor:theme.greenBright, marginBottom:6 }} />
                    <div style={{ fontSize:10, color:theme.textLight, marginBottom:2 }}>Left / Right</div>
                    <input type="range" min="0" max="100" value={photoOffsetX} onChange={async e => { const v = Number(e.target.value); setPhotoOffsetX(v); await supabase.from("profiles").update({ photo_offset_x: v }).eq("id", currentUser.id); }} style={{ width:"100%", accentColor:theme.greenBright }} />
                  </>
                )}
              </div>
            )}

            <label style={{ cursor:"pointer" }}>
              <div style={{ background:theme.greenBright, color:"white", fontWeight:700, fontSize:13, padding:"7px 18px", borderRadius:50, fontFamily:"'DM Sans',sans-serif" }}>{uploading ? "⏳ Uploading..." : user.photo_url ? "📷 Change photo" : "📷 Add profile photo"}</div>
              <input type="file" accept="image/*" style={{ display:"none" }} onChange={handlePhotoUpload} />
            </label>
          </div>
          <div style={{ fontFamily: "Georgia,serif", fontSize: 22, fontWeight: 700, color: theme.greenDeep }}>{user.name}, {user.age}</div>
          <div style={{ color: theme.textMid, fontSize: 13, marginTop: 3 }}>📍 {user.city}</div>
