const DummyMonitor = () => {
  const [stats, setStats] = useState(null);
  useEffect(() => {
    supabase.from("profiles").select("id", { count: "exact", head: true }).then(({ count: total }) => {
      const realCount = total || 0;
      let status, color, advice;
      if (realCount < 20) { status = "🟢 Dummies active"; color = "#52b788"; advice = `${realCount} real users. Dummies helping populate Discover.`; }
      else if (realCount < 50) { status = "🟡 Consider reducing"; color = "#f4a829"; advice = `${realCount} real users. Start removing some dummies.`; }
      else { status = "🔴 Remove dummies now"; color = "#e07a5f"; advice = `${realCount} real users. Dummies should be disabled.`; }
      setStats({ realCount, status, color, advice });
    });
  }, []);
  if (!stats) return null;
  return (
    <div style={{ background: "white", borderRadius: 14, border: `2px solid ${stats.color}`, margin: "0 0 8px", padding: "12px 16px" }}>
      <div style={{ fontWeight: 700, fontSize: 13, color: stats.color, marginBottom: 4 }}>{stats.status}</div>
      <div style={{ fontSize: 12, color: "#666" }}>{stats.advice}</div>
    </div>
  );
};

